SELECT try_divide(100.0 * SUM(customers),(SELECT SUM(customers) FROM workspace.segmentation_eval.segments)) AS percentage_of_customers
FROM workspace.segmentation_eval.segments
WHERE value_tier = 'C4' AND buying_style = 'B1' AND customers IS NOT NULL;

SELECT SUM(segments.expected_revenue) AS total_expected_revenue_outside_low_value_tier
FROM workspace.segmentation_eval.segments
WHERE segments.value_tier IN ('C1', 'C2', 'C3') AND segments.expected_revenue IS NOT NULL AND segments.value_tier IS NOT NULL;

SELECT try_divide(SUM(segments.expected_revenue),SUM(segments.customers)) AS revenue_per_customer
FROM workspace.segmentation_eval.segments
WHERE segments.buying_style = 'B2' AND segments.expected_revenue IS NOT NULL AND segments.customers IS NOT NULL;
